const { run } = require("../lib/runner");
const assert = require("assert");
let out = "";
const orig = console.log;
console.log = (s) => { out += s + "\n"; };
run("prod");
run("staging");
console.log = orig;
assert.ok(out.includes("deploy prod timeout=30000"), out);
assert.ok(out.includes("deploy staging timeout=15000"), out);
console.log("deploy tests passed");
